def t(pl, en, tag='span', cls='', extra=''):
    return f'<{tag} data-pl="{escape(pl, quote=True)}" data-en="{escape(en, quote=True)}"'+(f' class="{cls}"' if cls else '')+(f' {extra}' if extra else '')+f'>{escape(pl)}</{tag}>'

