def link(href, pl, en, cls='link-arrow', arrow='diagonal', external=False, extra=''):
    ext = ' target="_blank" rel="noopener noreferrer"' if external else ''
    tail = t(' (nowa karta)', ' (new tab)', cls='sr-only') if external else ''
    return f'<a href="{escape(href,quote=True)}" class="{cls}"{ext} {extra}>'+t(pl,en)+icon(arrow)+tail+'</a>'

def eyebrow(pl,en): return t(pl,en,'div','eyebrow')
def para(pl,en,cls=''): return t(pl,en,'p',cls)
def heading(pl,en,tag='h2',cls=''): return t(pl,en,tag,cls)
def logo(): return '<span class="logo-well"><img class="brand-logo" src="assets/cereaxis-labs-logo.png" alt="Cereaxis Labs" width="1520" height="264" decoding="async"></span>'
def list_html(items,cls='check-list'):
    return f'<ul class="{cls}">'+''.join(t(pl,en,'li') for pl,en in items)+'</ul>'

