    board=f'''<div><div class="system-board"><div class="board-top"><span>CEREAXIS LABS / 01</span><div class="board-dot"><i></i><i></i><i></i></div></div>{heading('Od biznesowego celu do połączonych rozwiązań.','From a business goal to connected solutions.','h2','board-heading')}<div class="system-map" aria-hidden="true"><svg viewBox="0 0 400 225" preserveAspectRatio="none"><path class="map-line" d="M200 95v35H60v43m140-43v43m0-43h140v43"/><path class="map-flow" d="M200 95v35H60v43m140-43v43m0-43h140v43"/></svg><div class="map-core"><img src="assets/cereaxis-labs-icon.png" alt="" width="512" height="512"></div><div class="map-node one"><div class="map-node-icon">{icon('workflow')}</div>{t('Automatyzacja','Automation')}</div><div class="map-node two"><div class="map-node-icon">{icon('web')}</div>{t('Strony WWW','Websites')}</div><div class="map-node three"><div class="map-node-icon">{icon('ai')}</div>{t('Integracje AI','AI integrations')}</div></div><div class="board-bottom">{t('Najpierw potrzeba. Potem technologia.','The need comes first. Technology follows.')}<span>{t('PROJEKT → INTEGRACJA → ROZWÓJ','DESIGN → CONNECT → DEVELOP')}</span></div></div>{para('Schemat obszarów współpracy · Cereaxis Labs','Areas of collaboration · Cereaxis Labs','board-caption')}</div>'''
