def contact():
    items=[(('Cel lub problem','Your goal or problem'),('Co chcesz usprawnić, zbudować lub połączyć? Wystarczy krótki opis sytuacji.','What would you like to improve, build or connect? A short description is enough.')),(('Obecny sposób działania','How things work today'),('Jakich narzędzi używasz i co sprawia najwięcej trudności?','Which tools do you use, and what is most difficult right now?')),(('Oczekiwany rezultat','Your expected outcome'),('Jak ma wyglądać lepsze rozwiązanie? Jeśli znasz ramy czasu i budżetu, możesz je wskazać.','What would a better solution look like? If you have a timeframe or budget in mind, you can share it.'))]
